float map(vec3 p) {
    vec3 w = p;
    float m = dot(w, w);
    float dz = 1.0;
    for (int i = 0; i < 6; i++) {
        float r = length(w);
        if (r > 2.0) break;
        float th = acos(clamp(w.y / r, -1.0, 1.0));
        float ph = atan(w.x, w.z);
        dz = 8.0 * pow(r, 7.0) * dz + 1.0;
        float r8 = pow(r, 8.0);
        th *= 8.0;
        ph *= 8.0;
        w = r8 * vec3(sin(th) * sin(ph), cos(th), sin(th) * cos(ph)) + p;
    }
    return 0.5 * log(length(w)) * length(w) / dz;
}
